CREATE TABLE IF NOT EXISTS shift_member_preferences (user_id INTEGER PRIMARY KEY,activity_level TEXT,meal_pattern TEXT,movement_preference TEXT,life_priority TEXT,tone TEXT,consent_scope TEXT NOT NULL DEFAULT 'personalisation_v1',preferences_json TEXT NOT NULL DEFAULT '{}',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shift_daily_plans (id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,local_date TEXT NOT NULL,context_json TEXT NOT NULL DEFAULT '{}',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,local_date));
CREATE TABLE IF NOT EXISTS shift_daily_actions (id TEXT PRIMARY KEY,plan_id TEXT NOT NULL,user_id INTEGER NOT NULL,local_date TEXT NOT NULL,position INTEGER NOT NULL,domain TEXT NOT NULL,title TEXT NOT NULL,detail TEXT NOT NULL,why_json TEXT NOT NULL DEFAULT '{}',source_json TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'planned',swap_count INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shift_daily_action_events (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,action_id TEXT NOT NULL,plan_id TEXT NOT NULL,local_date TEXT NOT NULL,decision TEXT NOT NULL,reason TEXT,idempotency_key TEXT NOT NULL,payload_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,idempotency_key));
CREATE INDEX IF NOT EXISTS idx_shift_daily_actions_user_date ON shift_daily_actions(user_id,local_date,position);
CREATE INDEX IF NOT EXISTS idx_shift_daily_events_user_date ON shift_daily_action_events(user_id,local_date,created_at);
